        <div className="toolbar"><TextInput className="search" size="l" placeholder="Поиск по имени, email или компании" value={query} onUpdate={v => {setQuery(v); setPage(1);}} hasClear startContent={<Icon data={Magnifier} size={17}/>} controlProps={{'"'aria-label': 'Поиск клиентов'}}/><div className=\"filters\"><Select size=\"l\" aria-label=\"Фильтр по статусу\" placeholder=\"Все статусы\" value={status ? [status] : []} onUpdate={v => {setStatus(v[0] || ''); setPage(1);}} options={statusOptions.map(value => ({value, content: value}))} hasClear/><Select size=\"l\" aria-label=\"Фильтр по тарифу\" placeholder=\"Все тарифы\" value={plan ? [plan] : []} onUpdate={v => {setPlan(v[0] || ''); setPage(1);}} options={planOptions.map(value => ({value, content: value}))} hasClear/>{(query || status || plan) && <Button view=\"flat-secondary\" onClick={resetFilters} aria-label=\"Сбросить фильтры\"><Icon data={Xmark}/></Button>}</div><div className=\"column-control\"><DropdownMenu open={columnsOpen} onOpenToggle={setColumnsOpen} renderSwitcher={p => <Button {...p} size=\"l\" view=\"outlined\"><Icon data={LayoutColumns3} size={16}/><span>Колонки</span></Button>}><div className=\"column-menu\"><Text variant=\"subheader-1\">Видимые колонки</Text>{Object.entries(columnNames).map(([id, title]) => <Checkbox key={id} checked={"'!hiddenColumns.includes(id)} onUpdate={checked => setHiddenColumns(prev => checked ? prev.filter(v => v !== id) : [...prev, id])}>{title}</Checkbox>)}</div></DropdownMenu></div></div>
