export type Client = {
  id: string; name: string; email: string; company: string;
  status: 'Активен' | 'Приглашён' | 'Неактивен';
  plan: 'Базовый' | 'Про' | 'Бизнес'; date: string; revenue: number; archived: boolean;
};
